function chooseReferenceEditRecipe(prompt=''){
  const text=String(prompt).toLowerCase();let best=null,bestScore=0;
  referenceEditRecipes.forEach(recipe=>{const score=recipe.keywords.reduce((total,keyword)=>total+(text.includes(keyword)?keyword.split(' ').length:0),0);if(score>bestScore){best=recipe;bestScore=score;}});
  return best;
}
