function detectRuntimeMode(){
  // iPadOS can use a desktop UA. All tablets share the touch controls while
  // Windows touch laptops retain the desktop studio at laptop widths.
  const ipad=/iPad/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1),phone=/Android.*Mobile|iPhone|iPod|Mobile/i.test(navigator.userAgent)||innerWidth<=767,tablet=!phone&&(ipad||/Android/i.test(navigator.userAgent)||innerWidth<=1023);
  runtimeMode.platform=phone?'mobile':tablet?'tablet':'desktop';
  runtimeMode.touch=runtimeMode.platform!=='desktop';
  runtimeMode.installed=matchMedia('(display-mode: standalone)').matches||Boolean(navigator.standalone);
  document.body.classList.toggle('platform-mobile',runtimeMode.platform==='mobile');
  document.body.classList.toggle('platform-desktop',runtimeMode.platform==='desktop');
  document.body.classList.toggle('platform-tablet',runtimeMode.platform==='tablet');
  document.body.classList.toggle('touch-workspace',runtimeMode.touch);
  document.body.classList.toggle('installed-app',runtimeMode.installed);
  document.body.dataset.platform=runtimeMode.platform;
}
detectRuntimeMode();

