function getAccounts(){try{return JSON.parse(localStorage.getItem(ACCOUNTS_KEY)||'[]');}catch{return [];}}
function loadCurrentUser(){try{const id=localStorage.getItem(SESSION_KEY);return getAccounts().find(account=>account.id===id)||null;}catch{return null;}}
function projectStorageKey(){return currentUser?`${STORAGE_KEY}:${currentUser.id}`:STORAGE_KEY;}
function mediaRecordKey(projectId,assetId){return `${currentUser?.id||'guest'}::${projectId}::${assetId}`;}
function openMediaDatabase(){
  if(mediaDatabasePromise)return mediaDatabasePromise;
  mediaDatabasePromise=new Promise((resolve,reject)=>{
    if(!('indexedDB' in window)){reject(new Error('Persistent media storage is unavailable'));return;}
    const request=indexedDB.open(MEDIA_DB_NAME,1);
    request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(MEDIA_STORE_NAME))db.createObjectStore(MEDIA_STORE_NAME,{keyPath:'key'});};
    request.onsuccess=()=>resolve(request.result);
    request.onerror=()=>reject(request.error||new Error('Could not open media storage'));
  });
  return mediaDatabasePromise;
}
async function storeProjectMedia(projectId,assetId,blob,{signal,userId=currentUser?.id||'guest'}={}){
  const db=await openMediaDatabase();
  if(signal?.aborted||(currentUser?.id||'guest')!==userId)throw new DOMException('Media save cancelled after the account changed.','AbortError');
  return new Promise((resolve,reject)=>{
    const transaction=db.transaction(MEDIA_STORE_NAME,'readwrite');
    const abort=()=>{try{transaction.abort();}catch{}},finish=(callback,value)=>{signal?.removeEventListener('abort',abort);callback(value);};signal?.addEventListener('abort',abort,{once:true});
    transaction.objectStore(MEDIA_STORE_NAME).put({key:`${userId}::${projectId}::${assetId}`,userId,projectId,assetId,blob,updatedAt:Date.now()});
    transaction.oncomplete=()=>finish(resolve,true);
    transaction.onerror=()=>finish(reject,transaction.error||new Error('Could not save media'));
    transaction.onabort=()=>finish(reject,new DOMException('Media save was interrupted.','AbortError'));
  });
}
async function getProjectMedia(projectId,assetId){
  const db=await openMediaDatabase();
  return new Promise((resolve,reject)=>{
    const request=db.transaction(MEDIA_STORE_NAME,'readonly').objectStore(MEDIA_STORE_NAME).get(mediaRecordKey(projectId,assetId));
    request.onsuccess=()=>resolve(request.result?.blob||null);
    request.onerror=()=>reject(request.error||new Error('Could not restore media'));
  });
}
async function restoreProjectMedia(projectId,assets){
  await Promise.all(assets.filter(asset=>asset.localFile).map(async asset=>{
    try{const blob=await getProjectMedia(projectId,asset.id);if(blob){asset.url=editorResources.createManagedUrl(blob);asset.persisted=true;}}
    catch(error){console.warn('Zorifi media restore failed',error);}
  }));
}
async function copyProjectMedia(sourceProjectId,targetProjectId,assets){
  await Promise.all((assets||[]).filter(asset=>asset.localFile).map(async asset=>{
    try{const blob=await getProjectMedia(sourceProjectId,asset.id);if(blob)await storeProjectMedia(targetProjectId,asset.id,blob);}
    catch(error){console.warn('Zorifi could not copy stored project media',error);}
  }));
}
async function deleteProjectMedia(projectId){
  try{
    const db=await openMediaDatabase(),userId=currentUser?.id||'guest';
    await new Promise((resolve,reject)=>{const transaction=db.transaction(MEDIA_STORE_NAME,'readwrite'),store=transaction.objectStore(MEDIA_STORE_NAME),request=store.openCursor();request.onsuccess=()=>{const cursor=request.result;if(!cursor)return;if(cursor.value?.projectId===projectId&&cursor.value?.userId===userId)cursor.delete();cursor.continue();};transaction.oncomplete=()=>resolve(true);transaction.onerror=()=>reject(transaction.error);transaction.onabort=()=>reject(transaction.error);});
  }catch(error){console.warn('Zorifi could not remove stored project media',error);}
}
async function deleteStoredMediaAsset(projectId,assetId){
  try{const db=await openMediaDatabase();await new Promise((resolve,reject)=>{const transaction=db.transaction(MEDIA_STORE_NAME,'readwrite');transaction.objectStore(MEDIA_STORE_NAME).delete(mediaRecordKey(projectId,assetId));transaction.oncomplete=resolve;transaction.onerror=()=>reject(transaction.error);transaction.onabort=()=>reject(transaction.error);});}catch(error){console.warn('Zorifi could not remove the stored media item',error);}
}
async function runMediaAction(action,assetId){
  const asset=state.mediaAssets.find(item=>item.id===assetId);if(!asset)return;
  if(action==='rename'){const name=prompt('Media name',asset.name)?.trim();if(!name)return;snapshot();asset.name=name.slice(0,100);state.clips.filter(clip=>clip.mediaId===asset.id).forEach(clip=>clip.name=asset.name);render();scheduleProjectSave(0);return;}
  if(action==='delete'){if(state.clips.some(clip=>clip.mediaId===asset.id))return toast('Remove this media from the timeline before deleting it');const library=asset.type==='audio'?'the Audio library':'Project Media';if(!confirm(`Delete “${asset.name}” from ${library}?`))return;state.mediaAssets=state.mediaAssets.filter(item=>item.id!==asset.id);if(asset.url?.startsWith('blob:'))revokeManagedUrl(asset.url);await deleteStoredMediaAsset(state.projectId,asset.id);render();scheduleProjectSave(0);toast(asset.type==='audio'?'Audio removed from this project':'Media removed from this project');}
}
function userInitials(){return (currentUser?.name||'User').split(/\s+/).slice(0,2).map(word=>word[0]).join('').toUpperCase();}
function userAvatarMarkup(){return currentUser?.avatar?`<img src="${esc(currentUser.avatar)}" alt="${esc(currentUser.name)}">`:userInitials();}
function normalizeIdentifier(value){const clean=value.trim().toLowerCase();return clean.includes('@')?clean:clean.replace(/[^\d+]/g,'');}
function validIdentifier(value){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)||/^\+?\d{7,15}$/.test(value);}
function bytesToHex(bytes){return [...bytes].map(value=>value.toString(16).padStart(2,'0')).join('');}
async function passwordHash(password,salt){
  const encoder=new TextEncoder(),key=await crypto.subtle.importKey('raw',encoder.encode(password),'PBKDF2',false,['deriveBits']),bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:encoder.encode(salt),iterations:120000,hash:'SHA-256'},key,256);return bytesToHex(new Uint8Array(bits));
}

function getSavedProjects() {
  try {
    if(!currentUser)return [];
    const saved=localStorage.getItem(projectStorageKey());
    if(saved) return JSON.parse(saved).map(ProjectModel.migrateProject).filter(Boolean).map(recoveredProject);
    return [];
  }
  catch { return []; }
}

function creatorStorageKey(kind){return `zorifi-${kind}-v1:${currentUser?.id||'guest'}`;}
