function getTemplates(){const currentBuiltins=new Map((CreatorPlatform.BUILTIN_TEMPLATES||[]).map(item=>[item.id,item])),saved=readCreatorCollection('templates').map(item=>{try{const builtin=item.builtin&&currentBuiltins.get(item.id);return CreatorPlatform.validateTemplate(builtin?{...builtin,favorite:item.favorite,usageCount:item.usageCount,lastUsedAt:item.lastUsedAt,updatedAt:item.updatedAt}:item);}catch{return null;}}).filter(Boolean),savedIds=new Set(saved.map(item=>item.id)),builtins=[...currentBuiltins.values()].filter(item=>!savedIds.has(item.id)).map(item=>CreatorPlatform.validateTemplate(item));return [...saved,...builtins];}
function saveTemplates(items){writeCreatorCollection('templates',items.map(CreatorPlatform.validateTemplate));}
