let aiAssetProviderCache=null;
async function updateAiAssetProviderDescription(kind,description){
  if(!description||!['image','music'].includes(kind))return;
  try{
    if(kind!=='music'&&(!aiAssetProviderCache||Date.now()-aiAssetProviderCache.at>10000)){const response=await fetch('/api/ai-settings',{cache:'no-store'});if(!response.ok)throw new Error('Provider settings unavailable');aiAssetProviderCache={at:Date.now(),configurations:(await response.json()).configurations||{}};}
    if(!description.isConnected)return;
    const config=kind==='music'?await getMusicProvider():aiAssetProviderCache.configurations[kind]||{},local=config.provider==='Local CPU',gemini=String(config.provider||'').startsWith('Gemini');
    const status=description.closest('.ai-asset-layout')?.querySelector('.compute-status small');
    if(status)status.textContent=`Execution path · ${local?'local CPU on this computer':gemini?'paid Gemini API':config.provider||'configured provider'}`;
    if(kind==='music'&&!config.configured){description.textContent=config.error||'Music generation is unavailable. Connect a music provider in AI settings.';const generate=description.closest('form')?.querySelector('.generate-ai-video');if(generate)generate.disabled=true;return;}
    if(kind==='image'){
      if(local){
        description.textContent='Create a square 512 × 512 PNG from a prompt on this computer. The first CPU render may take over a minute; no cloud generation charge applies.';
        const form=description.closest('form'),mode=form?.elements.mode,ratio=form?.elements.ratio,quality=form?.elements.resolution;
        if(mode){mode.value='text';mode.disabled=true;mode.closest('label').firstChild.textContent='Mode · prompt only';}
        if(ratio){ratio.value='1:1';ratio.disabled=true;ratio.closest('label').firstChild.textContent='Format · square';}
        if(quality){quality.innerHTML='<option value="standard">512 × 512 · CPU</option>';quality.disabled=true;}
        aiAssetReference=null;
        form?.querySelector('.ai-reference-input')?.setAttribute('hidden','');
        const generate=form?.querySelector('.generate-ai-video');if(generate&&aiAssetDraft?.status==='complete')generate.textContent='Generate another image';
        const another=description.closest('.ai-asset-layout')?.querySelector('[data-ai-asset-retry]');if(another&&aiAssetDraft?.status==='complete')another.textContent='Create another';
      }else if(gemini){
        description.textContent='Create images from a prompt or reference with Gemini. Gemini image generation requires a paid API tier and each request may incur a charge.';
        const quality=description.closest('form')?.elements.resolution;if(quality)quality.innerHTML='<option value="standard">1K image</option>';
      }
    }else if(local){
      description.textContent='Create a short instrumental WAV from a prompt on this computer. Duration is 5–30 seconds; no cloud generation charge applies.';
      const form=description.closest('form'),duration=form?.elements.duration,vocals=form?.elements.vocals;
      if(duration){duration.min='5';duration.max='30';if(Number(duration.value)>30||!aiAssetDraft?.input)duration.value='10';duration.closest('label').firstChild.textContent='Duration · 5–30 seconds';}
      if(vocals){vocals.value='instrumental';vocals.disabled=true;vocals.closest('label').firstChild.textContent='Vocals · instrumental';}
      const generate=form?.querySelector('.generate-ai-video');if(generate&&aiAssetDraft?.status==='complete')generate.textContent='Generate another clip';
      const another=description.closest('.ai-asset-layout')?.querySelector('[data-ai-asset-retry]');if(another&&aiAssetDraft?.status==='complete')another.textContent='Create another';
    }else if(gemini){
      description.textContent='Create a real 30-second MP3 from a prompt with Gemini Lyria. Music generation requires a paid API tier and each request may incur a charge.';
      const duration=description.closest('form')?.elements.duration;if(duration){duration.value='30';duration.disabled=true;duration.closest('label').firstChild.textContent='Duration · fixed 30 seconds';}
    }
  }catch{if(description.isConnected)description.textContent='Provider settings are unavailable. Check the local server and try again.';}
}
async function startAiAssetGeneration(event){
  event?.preventDefault();
  const form=event?.currentTarget;if(!form)return;
  const kind=aiGenerationKind;
  const input=kind==='image'?{prompt:form.elements.prompt.value,mode:form.elements.mode.value,ratio:form.elements.ratio.value,style:form.elements.style.value,resolution:form.elements.resolution.value,reference:aiAssetReference}:kind==='voice'?{prompt:form.elements.prompt.value,mode:'text',voice:form.elements.voice.value,language:form.elements.language.value,style:form.elements.style.value,speed:Number(form.elements.speed.value)}:{prompt:form.elements.prompt.value,mode:'text',genre:form.elements.genre.value,mood:form.elements.mood.value,duration:Number(form.elements.duration.value),tempo:Number(form.elements.tempo.value),instrumentation:form.elements.instrumentation.value,energy:Number(form.elements.energy.value),vocals:form.elements.vocals.value};
  const provider=kind==='music'?await getMusicProvider(true):await aiProviderDetails(kind);
  if(kind==='music'&&!provider.configured){aiAssetDraft={kind,status:AIProvider.STATES.FAILED,error:provider.error||'Music generation is unavailable. Connect a music provider in AI settings.',input};renderAiVideo();return;}
  if(provider.provider==='Local CPU'&&kind==='image')Object.assign(input,{mode:'text',ratio:'1:1',resolution:'standard',reference:null});
  if(provider.provider==='Local CPU'&&kind==='music')Object.assign(input,{mode:'text',duration:Math.max(5,Math.min(30,input.duration||10)),vocals:'instrumental'});
  try{
    let updateManaged=()=>{};
    aiAssetJob=new AIProvider.Job(kind,input,{transport:kind==='music'?musicJobTransport(provider):aiProviderTransport,pollInterval:1500,onUpdate:value=>{aiAssetDraft={...value,input};const stage=value.status==='running'?'generating':value.status==='complete'?'processing':value.status;try{if(AIPlatform.STAGES.includes(stage))updateManaged({stage,progress:value.progress,result:value});}catch{}renderAiVideo();}});
    const managed=aiGenerationManager.create({type:kind,provider:provider.provider||'configured provider',model:provider.model||'configured model',prompt:input.prompt,projectId:state.projectId,run:async({update})=>{updateManaged=update;const result=await aiAssetJob.start();if(result?.status==='complete')update({stage:'downloading',progress:result.progress,result});return result;},cancel:()=>aiAssetJob.cancel()});
    aiManagedGenerationId=managed.id;
    await aiGenerationManager.start(managed.id);
  }catch(error){if(error?.name!=='AbortError')toast(error.message||'Generation failed');}
  finally{aiManagedGenerationId='';}
}
