  state.mediaAssets.unshift(asset);const audioKind=result.kind==='music'||result.kind==='voice',duration=result.kind==='image'?5:Math.max(1,asset.duration||30),track=chooseTrack(audioKind?'audio':'video',state.currentTime,duration,true),clip={id:`generated-clip-${Date.now()}`,mediaId:asset.id,type:audioKind?'audio':'video',name:asset.name,start:state.currentTime,duration,sourceStart:0,track,opacity:100,volume:100,playbackRate:1,scale:100,positionX:0,positionY:0,rotation:0,fit:'cover',generated:true,audioEffects:audioKind?{role:result.kind==='voice'?'voiceover':'music'}:undefined};state.clips.push(clip);state.selected=clip.id;recalculateDuration();state.view='editor';aiAssetDraft=null;render();scheduleProjectSave(0);toast(`${capitalize(result.kind)} added to Media and the timeline`);
