  wrap.querySelectorAll('[data-provider-remove]').forEach(button=>button.onclick=async()=>{const type=button.dataset.providerRemove;if(!confirm(`Remove the configured ${type} provider?`))return;const response=await fetch('/api/ai-settings',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({removeProvider:type})}),data=await response.json();if(!response.ok)return toast(data.error||'Provider could not be removed');close();toast(`${capitalize(type)} provider removed`);});
