  if(!await configuredAiProvider('video')){aiVideoDraft={...options,engine:'motion',status:'error',error:'This video generation provider isn’t configured yet. Open Vanessa AI Provider settings, add the required credential and model, then use Test connection.'};renderAiVideo();return;}
  if(mode!=='text'&&!images.length){aiVideoDraft={...options,engine:'motion',status:'error',error:mode==='image'?'Choose a starting image first.':'Add at least one reference image first.'};renderAiVideo();return;}
  aiVideoDraft={...options,engine:'motion',status:'submitting',progress:null,requests:[]};renderAiVideo();let requests=[];
  const managed=aiGenerationManager.create({type:'video',provider:'configured video provider',model:'configured model',prompt,projectId:state.projectId,run:async({update})=>{update({stage:'generating',progress:null});requests=await Promise.all(Array.from({length:variations},async(_,index)=>{const response=await vanessaFetch(vanessaEndpoint('vanessa-motion'),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'start',prompt:`${prompt}${variations>1?` Variation ${index+1}: use a distinct but coherent camera interpretation.`:''}`,mode,duration,ratio,style,resolution,sound,direction,marketing,image:mode==='image'?images[0]:undefined,references:mode==='reference'?images:undefined})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Vanessa Motion could not start.');return {id:data.requestId,status:data.status||'pending',videoUrl:'',progress:Number.isFinite(Number(data.progress))?Number(data.progress):null};}));if(aiGenerationCancelled)throw new DOMException('Cancelled','AbortError');aiVideoDraft={...aiVideoDraft,status:'generating',progress:null,requests};renderAiVideo();update({stage:'processing',progress:null});const completed=await Promise.all(requests.map((request,index)=>pollVanessaMotion(request,index,requests.length)));if(aiGenerationCancelled)throw new DOMException('Cancelled','AbortError');update({stage:'downloading',progress:null});const videoUrls=completed.map(item=>item.videoUrl).filter(Boolean);if(!videoUrls.length)throw new Error('No completed video was returned.');return {status:'complete',kind:'video',requests:completed,videoUrls,videoUrl:videoUrls[0],url:videoUrls[0],prompt};},cancel:async()=>{aiGenerationCancelled=true;await Promise.allSettled(requests.filter(item=>item.id).map(item=>vanessaFetch(vanessaEndpoint('vanessa-motion'),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'cancel',requestId:item.id})})));}});aiManagedGenerationId=managed.id;
  try{const result=await aiGenerationManager.start(managed.id);if(!result||aiGenerationCancelled)return;aiVideoDraft={...aiVideoDraft,status:'ready',progress:100,requests:result.requests,videoUrls:result.videoUrls,videoUrl:result.videoUrl,title:prompt.slice(0,72)};renderAiVideo();const message=`Your ${result.videoUrls.length>1?`${result.videoUrls.length} video variations are`:'AI video is'} ready.`;toast(message);speakAsVanessa(message);if(auto)setTimeout(()=>createAiProject({automatic:true}),450);}catch(error){if(aiGenerationCancelled||error?.name==='AbortError')return;aiVideoDraft={...aiVideoDraft,status:'error',error:error.message||'Video generation could not finish.'};renderAiVideo();}finally{aiManagedGenerationId='';}
