  operations.forEach(operation=>{const p=operation.parameters,target=operation.target;if(operation.type==='add_clip'){const asset=state.mediaAssets.find(item=>item.id===target.mediaId);if(!asset)return;const clipType=asset.type==='image'?'image':'video',track=chooseTrack('video',p.start,p.duration,Number(p.layer)>0),overlay=isOverlayTrack(track);state.clips.push({id:`scene-clip-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,type:clipType,name:asset.name,start:p.start,duration:p.duration,sourceStart:0,track,opacity:100,volume:clipType==='video'?100:0,playbackRate:p.pacing==='fast'?1.15:p.pacing==='slow'?0.9:1,scale:overlay?72:100,positionX:0,positionY:0,rotation:0,fit:overlay?'contain':'cover',blendMode:'normal',transition:p.transition==='none'?null:p.transition,transitionDuration:Math.min(.6,p.duration*.25),autoMotion:motions[state.clips.filter(clip=>clip.sceneGenerated&&(clip.type==='video'||clip.type==='image')).length%motions.length],mediaId:asset.id,sceneGenerated:true,sceneId:target.sceneId,overlay});}if(operation.type==='add_text'){state.clips.push({id:`scene-text-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,type:'text',name:p.text,start:p.start,duration:p.duration,track:chooseTrack('text',p.start,p.duration,true),opacity:100,volume:100,playbackRate:1,fontId:'modern',fontFamily:'Arial, sans-serif',fontSize:valid.direction==='energetic'?38:30,fontWeight:valid.direction==='energetic'?900:700,color:'#ffffff',align:'center',style:valid.direction==='energetic'?'word-caption':'shadow',bottom:12,letterSpacing:'-.02em',background:'transparent',sceneGenerated:true,sceneId:target.sceneId});}if(operation.type==='add_effect'){state.clips.push({id:`scene-fx-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,type:'effect',effectId:target.effectId,name:effects.find(item=>item.id===target.effectId)?.name||'Scene effect',start:p.start,duration:p.duration,track:chooseTrack('effect',p.start,p.duration,true),strength:p.strength,fade:.2,opacity:100,volume:100,sceneGenerated:true,sceneId:target.sceneId});}if(operation.type==='add_audio'){state.clips.push({id:`scene-audio-${Date.now()}`,type:'audio',name:state.mediaAssets.find(item=>item.id===target.mediaId)?.name||'Scene audio',start:0,duration:p.duration,sourceStart:0,track:chooseTrack('audio',0,p.duration,true),opacity:100,volume:p.level,playbackRate:1,mediaId:target.mediaId,sceneGenerated:true,sceneId:'scene-audio'});}});state.scenePlan=valid;state.duration=Math.max(1,valid.scenes.reduce((sum,scene)=>sum+scene.duration,0));state.currentTime=0;state.hasCaptions=false;state.activePanel='media';state.selected=state.clips.find(clip=>clip.type==='video'||clip.type==='image')?.id||null;state.view='editor';recalculateDuration();render();saveProject();
