  const library=`<div class="search">${icons.search}<input placeholder="Search ${section==='filters'?'filters':'effects'}" data-effect-search /></div>${section==='effects'?`<div class="effect-tabs">${categories.map((category,index)=>`<button class="${index===0?'active':''}" data-category="${category}">${category}</button>`).join('')}</div>`:''}<div class="effects-grid">${effectLibrary.map(effectCard).join('')}</div>`;
  const packs=`<div class="edit-pack-intro"><span>✦</span><div><b>Reference-style edit packs</b><small>Apply the motion, colour, transition and impact treatment to the selected clip. Every setting remains editable.</small></div></div><div class="edit-pack-grid">${editPacks.map(pack=>`<button data-edit-pack="${pack.id}"><i>${pack.badge}</i><span><b>${pack.name}</b><small>${pack.description}</small></span><em>Apply</em></button>`).join('')}</div><div class="edit-pack-features"><b>Tools included</b><span>Beat flash</span><span>Punch zoom</span><span>Camera shake</span><span>Subject outline</span><span>Echo trails</span><span>Particles</span><span>Light sweep</span><span>Speed ramp</span><span>Dark vignette</span><span>Kinetic text</span></div>`;
