  const quality=`<div class="quality-hero"><span>HD</span><div><b>Video quality</b><small>Clean, balance and stabilize selected footage.</small></div></div><div class="quality-grid">${[['enhance','HD','Enhance quality','Sharper detail and balanced contrast'],['denoise','DN','Reduce noise','Clean low-light and compressed footage'],['auto-color','AC','Auto colour','Balance exposure and colour'],['stabilize','ST','Stabilize','Smooth handheld movement'],['sharpen','SH','Smart sharpen','Restore edge clarity'],['deflicker','DF','De-flicker','Reduce pulsing light changes']].map(([id,badge,name,description])=>`<button data-quality-action="${id}"><i>${badge}</i><span><b>${name}</b><small>${description}</small></span></button>`).join('')}</div>`;
