  document.querySelectorAll('[data-autocut-spatial-field]').forEach(control=>{control.addEventListener('input',()=>{const clip=state.clips.find(item=>item.id===state.selected),field=control.dataset.autocutSpatialField;if(!clip?.spatial3D||!window.ZorifiToolRegistry)return;if(trackState(clip.track).locked)return;try{const next=ZorifiToolRegistry.validateParams('spatial',{...clip.spatial3D,[field]:Number(control.value)});if(!control.dataset.spatialSnapshot){snapshot();control.dataset.spatialSnapshot='true';}clip.spatial3D=next;clip.autoCutToolsApplied=true;const output=document.querySelector(`[data-autocut-spatial-output="${field}"]`);if(output)output.textContent=Number(next[field].toFixed(2))+(control.dataset.autocutSpatialUnit||'');renderChromaPreviews();}catch(error){toast(error.message);}});control.addEventListener('change',()=>{delete control.dataset.spatialSnapshot;scheduleProjectSave(0);});});
  document.querySelector('[data-autocut-cutout-load]')?.addEventListener('click',async event=>{const button=event.currentTarget,clipId=state.selected,clip=state.clips.find(item=>item.id===clipId);if(clip?.type!=='video')return;if(trackState(clip.track).locked)return toast('Unlock this track before enabling person cutout.');if(!window.ZorifiPersonCutout)return toast('The person cutout engine is unavailable. Refresh Zorifi.');button.disabled=true;const progress=document.querySelector('[data-autocut-cutout-progress]');try{await ZorifiPersonCutout.prepare({allowDownload:true,onProgress:update=>{if(progress)progress.textContent=update.stage==='ready'?'Person model ready.':`${update.stage==='runtime'?'Loading runtime':update.stage==='model'?'Downloading person model':'Preparing local model'}${update.stage==='model'?` · ${Math.round(update.progress*100)}%`:''}…`;}});const current=state.clips.find(item=>item.id===clipId);if(current&&current.type==='video'&&!trackState(current.track).locked){snapshot();current.autoCutStyle||={motion:'none',grade:'natural',caption:'',transition:'cut'};current.subjectCutout={enabled:true,threshold:current.subjectCutout?.threshold??.45,softness:current.subjectCutout?.softness??.12};current.autoCutToolsApplied=true;scheduleProjectSave(0);}render();toast('Person cutout is ready on this device.');}catch(error){button.disabled=false;if(progress)progress.textContent=error.message||'The model could not be loaded.';toast(error.message||'Person cutout could not be enabled.');}});
  const setCutoutEnabled=enabled=>{const clip=state.clips.find(item=>item.id===state.selected);if(clip?.type!=='video')return;if(trackState(clip.track).locked)return toast('Unlock this track before changing person cutout.');if(enabled&&!window.ZorifiPersonCutout?.ready())return toast('Download the person model before enabling cutout.');snapshot();clip.autoCutStyle||={motion:'none',grade:'natural',caption:'',transition:'cut'};clip.subjectCutout={...clip.subjectCutout,enabled,threshold:clip.subjectCutout?.threshold??.45,softness:clip.subjectCutout?.softness??.12};clip.autoCutToolsApplied=true;render();scheduleProjectSave(0);};
