function closeProjectSwitcher(){
  document.querySelector('[data-project-switcher]')?.remove();
  const trigger=document.querySelector('[data-action="switch-project"]');
  if(trigger)trigger.setAttribute('aria-expanded','false');
}

function showProjectSwitcher(anchor){
  closeProjectSwitcher();
  saveProject();
  const projects=getSavedProjects().sort((a,b)=>new Date(b.updatedAt||0)-new Date(a.updatedAt||0));
  const menu=document.createElement('div');
  menu.className='project-switcher';menu.dataset.projectSwitcher='';menu.setAttribute('role','menu');
  menu.innerHTML=`<header><div><b>Switch project</b><small>${projects.length} saved ${projects.length===1?'project':'projects'}</small></div><button type="button" data-project-switch-close aria-label="Close project switcher">×</button></header><div class="project-switch-list">${projects.map(project=>{const active=project.id===state.projectId,thumb=projectThumbnail(project);return `<button type="button" class="project-switch-item ${active?'active':''}" data-switch-project-id="${esc(project.id)}" role="menuitem" ${active?'aria-current="true"':''}>${thumb?`<img src="${esc(thumb)}" alt="">`:`<i>${icons.video}</i>`}<span><b>${esc(project.name)}</b><small>${active?'Currently open':`Saved ${relativeTime(project.updatedAt)}`}</small></span><em>${active?'✓':'›'}</em></button>`;}).join('')||'<p class="project-switch-empty">No saved projects yet.</p>'}</div><footer><button type="button" data-project-versions>Versions</button><button type="button" data-switch-project-home>View all projects</button><button type="button" class="new" data-switch-project-new>${icons.plus}<span>New project</span></button></footer>`;
  document.body.appendChild(menu);
  const rect=anchor.getBoundingClientRect(),menuWidth=Math.min(360,innerWidth-24);
  menu.style.width=`${menuWidth}px`;menu.style.top=`${Math.min(innerHeight-menu.offsetHeight-12,rect.bottom+8)}px`;menu.style.left=`${Math.max(12,Math.min(innerWidth-menuWidth-12,rect.left))}px`;
  anchor.setAttribute('aria-expanded','true');
  menu.querySelector('[data-project-switch-close]')?.addEventListener('click',closeProjectSwitcher);
  menu.querySelector('[data-switch-project-home]')?.addEventListener('click',()=>{closeProjectSwitcher();handle('home',anchor);});
  menu.querySelector('[data-project-versions]')?.addEventListener('click',()=>{closeProjectSwitcher();showProjectVersions();});
  menu.querySelector('[data-switch-project-new]')?.addEventListener('click',()=>{closeProjectSwitcher();openProject('new');});
  menu.querySelectorAll('[data-switch-project-id]').forEach(button=>button.addEventListener('click',async()=>{
    const projectId=button.dataset.switchProjectId;if(projectId===state.projectId){closeProjectSwitcher();return;}
    closeProjectSwitcher();stopProjectPlayback('project-switch');saveProject();
    const project=getSavedProjects().find(item=>item.id===projectId);if(!project){toast('That project could not be found');return;}
    await loadProject(project);state.view='editor';render();toast(`${state.currentProject} opened`);
  }));
  const dismiss=event=>{if(!menu.contains(event.target)&&event.target!==anchor&&!anchor.contains(event.target)){closeProjectSwitcher();document.removeEventListener('pointerdown',dismiss,true);}};
  setTimeout(()=>document.addEventListener('pointerdown',dismiss,true),0);
  menu.querySelector('.project-switch-item')?.focus();
}

function liveUpdateInspectorField(el){
  const clip=state.clips.find(item=>item.id===state.selected);if(!clip||trackState(clip.track).locked)return;
  const field=el.dataset.field,liveFields=['sourceStart','scale','positionX','positionY','rotation','rotationX','rotationY','opacity','volume','maskFeather','maskScale','maskWidth','maskHeight','maskRotation','maskX','maskY','chromaStrength','chromaTolerance','chromaSoftness','chromaSpill','trackingStrength','transitionDuration','adjustExposure','adjustContrast','adjustSaturation','adjustHue','adjustBlur','anchorX','anchorY','strokeWidth','clipExposure','clipContrast','clipSaturation','clipBlur','cornerRadius','audioFadeIn','audioFadeOut','audioPan'];if(!liveFields.includes(field))return;
  if(el.dataset.liveSnapshot!=='true'){snapshot();el.dataset.liveSnapshot='true';}
  if(KEYFRAME_EDITABLE_PROPERTIES.has(field))activeKeyframeProperty=field;
  setEditableClipValue(clip,field,Number(el.value));
  if(field==='strokeWidth')refreshGeneratedLayerAsset(clip);
  const valueLabel=el.closest('.field')?.querySelector('label span:last-child'),suffix=['rotation','rotationX','rotationY'].includes(field)?'°':['sourceStart','audioFadeIn','audioFadeOut'].includes(field)?'s':['maskFeather','clipBlur','strokeWidth'].includes(field)?'px':['clipExposure','clipContrast','audioPan'].includes(field)?'':'%';if(valueLabel)valueLabel.textContent=`${Number(el.value).toFixed(['sourceStart','audioFadeIn','audioFadeOut','clipBlur'].includes(field)?1:0)}${suffix}`;
  if(field==='positionX'||field==='positionY')showAlignmentGuide(field,clip);
  const source=document.querySelector(`[data-preview-clip="${clip.id}"]`);
  if(source){applyLiveMotionStyle(source,clip);if(field==='sourceStart'&&source.tagName==='VIDEO')source.currentTime=Math.min(clip.sourceStart||0,Math.max(0,(source.duration||0)-.02));if(field==='volume'&&source.tagName==='VIDEO')applyPreviewVideoAudio(source,clip);if(field.startsWith('chroma')||clip.autoCutStyle)renderChromaPreviews();}
}

function showAlignmentGuide(field,clip){
  const preview=document.querySelector('.preview');if(!preview)return;
  preview.classList.remove('guide-x','guide-y','guide-centered');
  if(!['move','positionX','positionY'].includes(field))return;
  let centeredX=Math.abs(keyframedValue(clip,'positionX'))<=.05,centeredY=Math.abs(keyframedValue(clip,'positionY'))<=.05;
  if(clip.type==='text'){
    const element=[...preview.querySelectorAll('[data-preview-text]')].find(item=>item.dataset.previewText===clip.id),content=element?.querySelector('.title-content')||element;
    if(!content)return;
    const frame=preview.getBoundingClientRect(),rect=content.getBoundingClientRect();
    centeredX=Math.abs(rect.left+rect.width/2-(frame.left+frame.width/2))<=2;
    centeredY=Math.abs(rect.top+rect.height/2-(frame.top+frame.height/2))<=2;
  }
  if(centeredX)preview.classList.add('guide-x');
  if(centeredY)preview.classList.add('guide-y');
  if(centeredX&&centeredY)preview.classList.add('guide-centered');
}

function runMobileClipAction(action){
  const clip=state.clips.find(item=>item.id===state.selected);if(!clip)return;
  if(action==='back'||action==='detach'){state.selected=null;state.mobileInspectorOpen=false;render();return;}
  if(action==='delete'){deleteClip();return;}
  if(action==='duplicate'){duplicateSelectedClip();return;}
  if(action==='split'){if(state.currentTime<=clip.start||state.currentTime>=clip.start+clip.duration)state.currentTime=clip.start+clip.duration/2;splitClip();return;}
  if(action==='replace'){pendingReplaceClipId=clip.id;filePicker.value='';filePicker.click();toast('Choose replacement media');return;}
  if(action==='animation'){state.activePanel='keyframes';state.mobileInspectorOpen=false;render();toast('Keyframes workspace opened');return;}
  if(['adjust','trim','speed','volume','opacity'].includes(action)){state.mobileInspectorOpen=true;render();toast(`${capitalize(action)} controls opened`);}
}

function showNotificationCenter(el){
  document.querySelector('[data-notification-center]')?.remove();
  const rect=el.getBoundingClientRect(),panel=document.createElement('section');panel.className='notification-center';panel.dataset.notificationCenter='';panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Notifications');panel.style.top=`${rect.bottom+8}px`;panel.style.right=`${Math.max(10,innerWidth-rect.right)}px`;panel.innerHTML=`<header><b>Notifications</b><button aria-label="Close notifications">×</button></header><article><i></i><span><b>Project is protected</b><small>${esc(state.currentProject)} is saved locally with recovery enabled.</small></span></article><article><i class="purple"></i><span><b>Vanessa is ready</b><small>Ask a question or request an edit without leaving the workspace.</small></span></article>`;document.body.appendChild(panel);panel.querySelector('button').onclick=()=>panel.remove();setTimeout(()=>document.addEventListener('pointerdown',event=>{if(!panel.contains(event.target)&&event.target!==el)panel.remove();},{once:true}),0);
}

function handle(action, el) {
  const actions = {
    import: () => filePicker.click(),
    'extract-audio': () => { extractAudioPicker.value=''; extractAudioPicker.click(); },
    logout,
    'account-settings': showAccountSettings,
    'support-center': () => showSupportCenter(),
    'beta-center': () => showSupportCenter('__beta__'),
    'switch-project': () => document.querySelector('[data-project-switcher]')?closeProjectSwitcher():showProjectSwitcher(el),
    scenes: openZorifiScenes,
    'ai-video': () => {state.view='ai-video';render();},
    vanessa: () => {state.mobileToolSheetOpen=false;vanessaOpen=true;render();requestAnimationFrame(()=>document.querySelector('.vanessa-panel input[name="message"]')?.focus({preventScroll:true}));},
    'home-section': () => {stopProjectPlayback('navigation');saveProject();if(el.dataset.homeTarget==='templates'){openTemplateFeed();return;}state.view='home';render();requestAnimationFrame(()=>requestAnimationFrame(()=>{const content=document.querySelector('.home-content'),target=document.querySelector(`[data-home-section="${el.dataset.homeTarget}"]`);if(content&&target)content.scrollTop=Math.max(0,target.offsetTop-18);}));},
    panel: () => { state.activePanel = el.dataset.panel;state.responsivePanel='tools';state.mobileToolSheetOpen=false;state.mobileInspectorOpen=false;if(runtimeMode.platform==='desktop')state.panelCollapsed=false;render(); },
    'responsive-tools': () => {state.responsivePanel=state.responsivePanel==='tools'?'':'tools';state.panelCollapsed=false;render();},
    'responsive-properties': () => {state.responsivePanel=state.responsivePanel==='inspector'?'':'inspector';state.inspectorCollapsed=false;render();},
    'graph-tool': () => {state.activePanel='keyframes';keyframeWorkspaceView='graph';if(runtimeMode.platform==='desktop')state.panelCollapsed=false;render();},
    home: () => {stopProjectPlayback('navigation');saveProject();state.view='home';render();},
    play: togglePlayback,
    'frame-back': () => stepFrame(-1),
    'frame-forward': () => stepFrame(1),
    'loop-playback': toggleLoopPlayback,
    'fullscreen-preview': fullscreenPreview,
    'jump-back': () => { seekProject(state.currentTime-5); render(); },
    'jump-forward': () => { seekProject(state.currentTime+5); render(); },
    split: splitClip,
    delete: deleteClip,
    'ripple-delete': rippleDelete,
    'toggle-snapping': () => {state.snapping=!state.snapping;render();toast(`Snapping ${state.snapping?'on':'off'}`);},
    'add-title': addTitle,
    captions: toggleCaptions,
    export: showExport,
    'save-now': () => {saveProject();toast('Project saved');},
    notifications: () => showNotificationCenter(el),
    undo: undo,
    redo: redo,
    shortcuts: showShortcutGuide,
    'toggle-panel': toggleToolPanel,
    'toggle-inspector': toggleInspector,
    'mobile-properties': () => {state.mobileInspectorOpen=true;render();},
    'mobile-track-controls': () => showMobileTrackControls(Number(el.dataset.track)),
    'close-mobile-properties': () => {state.mobileInspectorOpen=false;render();},
    'mobile-tools': () => {state.mobileToolSheetOpen=!state.mobileToolSheetOpen;state.mobileInspectorOpen=false;render();},
    'close-mobile-tools': () => {state.mobileToolSheetOpen=false;render();},
    'mobile-timeline': () => {state.mobileTimelineExpanded=!state.mobileTimelineExpanded;state.mobileToolSheetOpen=false;state.mobileInspectorOpen=false;mobileHaptic(14);render();toast(state.mobileTimelineExpanded?'Timeline focus opened · pinch to zoom':'Balanced mobile workspace restored');},
    'mobile-duplicate': () => {mobileHaptic(10);duplicateSelectedClip();},
    'mobile-templates': openMobileTemplates,
    'mobile-music-editor': () => {state.mobileToolSheetOpen=false;mobileHaptic(12);createMusicProject();},
    'toggle-timeline': toggleTimeline,
    'timeline-height-down': () => changeTimelineHeight(-40),
    'timeline-height-up': () => changeTimelineHeight(40),
    mute: togglePreviewMute,
    ratio: () => { state.ratio = el.value.replace(':',' / '); state.frameWidth=null; state.frameHeight=null; render(); },
    zoom: () => applyTimelineZoom(Number(el.value)),
    'zoom-fit': fitTimelineZoom,
    'zoom-out': () => changeTimelineZoom(-10),
    'zoom-in': () => changeTimelineZoom(10)
  };
  actions[action]?.();
}

function toggleToolPanel(){if(runtimeMode.platform!=='desktop')return;state.panelCollapsed=!state.panelCollapsed;render();toast(state.panelCollapsed?'Tool panel minimized':'Tool panel expanded');}
function toggleInspector(){if(runtimeMode.platform!=='desktop')return;state.inspectorCollapsed=!state.inspectorCollapsed;render();toast(state.inspectorCollapsed?'Properties minimized':'Properties expanded');}
function toggleTimeline(){if(runtimeMode.platform!=='desktop')return;state.timelineCollapsed=!state.timelineCollapsed;render();toast(state.timelineCollapsed?'Timeline minimized':'Timeline expanded');}
function timelineHeightBounds(){
  const viewport=Math.max(480,Number(window.innerHeight)||800),minimum=editorWorkspaceMode==='music'?210:220;
  const maximum=editorWorkspaceMode==='music'?Math.max(minimum,Math.min(520,Math.floor(viewport*.42))):Math.max(minimum,Math.min(600,viewport-260));
  return {minimum,maximum};
}
function setTimelineHeight(value,{announce=false,persist=false}={}){
  const {minimum,maximum}=timelineHeightBounds();
  state.timelineHeight=Math.round(Math.max(minimum,Math.min(maximum,Number(value)||state.timelineHeight||330)));
  state.timelineCollapsed=false;
  const shell=document.querySelector('.app-shell'),handle=document.querySelector('[data-timeline-resize]');
  shell?.classList.remove('timeline-collapsed');shell?.style.setProperty('--timeline-height',`${state.timelineHeight}px`);handle?.setAttribute('aria-valuenow',String(state.timelineHeight));
  if(persist)saveProject();else scheduleProjectSave(180);
  if(announce)toast(`Timeline height · ${state.timelineHeight}px`);
  return state.timelineHeight;
}
function changeTimelineHeight(delta){if(runtimeMode.platform!=='desktop')return;setTimelineHeight(state.timelineHeight+delta,{announce:true,persist:true});}
function setupPanelResize(){
  if(runtimeMode.platform!=='desktop')return;
  const handle=document.querySelector('[data-panel-resize]'),workspace=document.querySelector('.workspace');
  if(handle&&workspace){
    handle.addEventListener('pointerdown',event=>{event.preventDefault();if(state.panelCollapsed){state.panelCollapsed=false;render();return;}const rect=workspace.getBoundingClientRect();document.body.classList.add('resizing-tool-panel');handle.setPointerCapture?.(event.pointerId);const move=pointer=>{state.panelWidth=Math.max(340,Math.min(620,pointer.clientX-rect.left));document.querySelector('.app-shell')?.style.setProperty('--panel-width',`${state.panelWidth}px`);};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);document.body.classList.remove('resizing-tool-panel');saveProject();};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);});
    handle.addEventListener('dblclick',()=>{state.panelWidth=380;state.panelCollapsed=false;render();toast('Tool panel width reset');});
    const inspectorHandle=document.querySelector('[data-inspector-resize]');inspectorHandle?.addEventListener('pointerdown',event=>{event.preventDefault();if(state.inspectorCollapsed){state.inspectorCollapsed=false;render();return;}const rect=workspace.getBoundingClientRect();document.body.classList.add('resizing-inspector');const move=pointer=>{state.inspectorWidth=Math.max(280,Math.min(520,rect.right-pointer.clientX));document.querySelector('.app-shell')?.style.setProperty('--inspector-width',`${state.inspectorWidth}px`);};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);document.body.classList.remove('resizing-inspector');saveProject();};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);});inspectorHandle?.addEventListener('dblclick',()=>{state.inspectorWidth=300;state.inspectorCollapsed=false;render();toast('Properties width reset');});
  }
  const timelineHandle=document.querySelector('[data-timeline-resize]');
  timelineHandle?.addEventListener('pointerdown',event=>{if(event.button!==0)return;event.preventDefault();if(state.timelineCollapsed){state.timelineCollapsed=false;render();return;}document.body.classList.add('resizing-timeline');timelineHandle.setPointerCapture?.(event.pointerId);const move=pointer=>setTimelineHeight(innerHeight-pointer.clientY);const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);document.body.classList.remove('resizing-timeline');saveProject();};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);});
  timelineHandle?.addEventListener('dblclick',()=>{setTimelineHeight(330,{announce:true,persist:true});});
  timelineHandle?.addEventListener('keydown',event=>{if(!['ArrowUp','ArrowDown','Home'].includes(event.key))return;event.preventDefault();if(event.key==='Home')setTimelineHeight(330,{announce:true,persist:true});else changeTimelineHeight(event.key==='ArrowUp'?20:-20);});
}

function bindTrackResizers(){
  if(runtimeMode.platform!=='desktop')return;
  document.querySelectorAll('[data-track-resize]').forEach(handle=>{
    handle.addEventListener('pointerdown',event=>{
      if(event.button!==0)return;
      event.preventDefault();event.stopPropagation();
      const track=Number(handle.dataset.trackResize),current=trackState(track);
      if(current.collapsed){current.collapsed=false;state.trackStates[track]=current;render();return;}
      const startY=event.clientY,startHeight=trackHeight(track);
      document.body.classList.add('resizing-track');
      const move=pointer=>{
        current.height=Math.max(32,Math.min(160,startHeight+(pointer.clientY-startY)));
        state.trackStates[track]=current;
        document.querySelectorAll(`[data-track-head="${track}"],[data-track-lane="${track}"]`).forEach(row=>row.style.height=`${current.height}px`);
      };
      const up=()=>{
        window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);
        document.body.classList.remove('resizing-track');saveProject();
        toast(`${trackLabel(track)} layer height saved`);
      };
      window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);
    });
    handle.addEventListener('dblclick',event=>{
      event.preventDefault();event.stopPropagation();
      const track=Number(handle.dataset.trackResize),current=trackState(track);
      current.height=52;current.collapsed=false;state.trackStates[track]=current;
      render();toast(`${trackLabel(track)} layer height reset`);
    });
  });
}

function updatePlaybackFrame(now=performance.now()){
  const head=document.querySelector('.playhead');if(head)head.style.left=`${state.currentTime/Math.max(.001,state.duration)*100}%`;
  const clock=document.querySelector('.transport .time strong');if(clock)clock.textContent=fmt(state.currentTime);
  document.querySelectorAll('[data-preview-clip]').forEach(element=>{const clip=state.clips.find(item=>item.id===element.dataset.previewClip);if(clip)applyLiveMotionStyle(element,clip,state.currentTime);});
  document.querySelectorAll('[data-preview-text]').forEach(element=>{const clip=state.clips.find(item=>item.id===element.dataset.previewText);if(clip)applyLiveTextStyle(element,clip,state.currentTime);});
  updatePreviewGlobalFilter(state.currentTime);syncAudioProcessing();
  const metrics=performanceMonitor.frame(now);if(now-lastPerformanceUiUpdate>750){lastPerformanceUiUpdate=now;activePreviewQuality=Phase9.previewPolicy({width:state.frameWidth||1920,height:state.frameHeight||1080,clips:state.clips.length,effects:state.clips.filter(item=>item.type==='effect').length,memoryGB:navigator.deviceMemory||8,averageFrameMs:metrics.averageFrameMs,requested:state.previewQuality});document.body.dataset.previewQuality=activePreviewQuality;const badge=document.querySelector('[data-performance-badge]');if(badge){badge.textContent=`${activePreviewQuality.toUpperCase()} · ${Math.round(metrics.fps)} FPS`;badge.title=`Measured ${metrics.averageFrameMs.toFixed(1)} ms per preview frame`;}}
  playbackSyncTick++;if(playbackSyncTick%(document.querySelector('[data-autocut-preview]')?2:3)===0)renderChromaPreviews();if(playbackSyncTick%6===0)syncVideo();
}
function stopAllPlaybackMedia(){
  document.querySelectorAll('video[data-preview-clip],audio[data-timeline-audio]').forEach(media=>{media.pause();media.loop=false;});
  stopTimelineAudio();if(audioPreview){audioPreview.pause();audioPreview=null;}
}
function projectTimeFromMedia(clip,sourceTime){
  const start=Math.max(0,Number(clip?.start)||0),end=start+Math.max(.001,Number(clip?.duration)||.001),target=Math.max(0,Number(sourceTime)||0);
  if(!clip?.speedRamp&&!clip?.keyframes?.playbackRate?.length)return Math.max(start,Math.min(end,start+(target-(Number(clip.sourceStart)||0))/Math.max(.01,Number(clip.playbackRate)||1)));
  let low=start,high=end;for(let index=0;index<22;index++){const middle=(low+high)/2;if(clipSourceTiming(clip,middle).sourceTime<target)low=middle;else high=middle;}return Math.max(start,Math.min(end,(low+high)/2));
}
function authoritativePlaybackMedia(){
  const videos=[...document.querySelectorAll('video[data-preview-clip]')].map(media=>({media,clip:state.clips.find(item=>item.id===media.dataset.previewClip)})).filter(item=>item.clip&&item.media.dataset.projectSeekTarget===undefined&&item.media.readyState>=2&&!item.media.paused&&!item.media.ended&&state.mediaAssets.find(asset=>asset.id===item.clip.mediaId)?.type==='video').sort((a,b)=>trackNumber(b.clip.track)-trackNumber(a.clip.track));
  if(videos.length)return videos[0];
  for(const [id,media] of timelineAudioPlayers){const clip=state.clips.find(item=>item.id===id);if(clip&&media.dataset.projectSeekTarget===undefined&&media.readyState>=2&&!media.paused&&!media.ended)return {media,clip};}
  return null;
}
function authoritativePlaybackTime(){const source=authoritativePlaybackMedia();return source?projectTimeFromMedia(source.clip,source.media.currentTime):null;}
function syncProjectFromMedia(media,clip,reason='media'){
  if(!state.playing||media!==authoritativePlaybackMedia()?.media)return;const time=projectTimeFromMedia(clip,media.currentTime);if(!Number.isFinite(time))return;state.currentTime=time;playbackController?.sample(reason);updatePlaybackFrame();
}
function bindPlaybackMediaClock(media,clip){
  if(media.dataset.projectClockBound==='true')return;media.dataset.projectClockBound='true';media.addEventListener('timeupdate',()=>syncProjectFromMedia(media,clip,'timeupdate'));media.addEventListener('seeking',()=>syncProjectFromMedia(media,clip,'seeking'));media.addEventListener('ended',()=>{if(!state.playing)return;const end=clip.start+clip.duration;if(end>=state.duration-.001&&!state.loopPlayback){seekProject(state.duration,{sync:false});stopProjectPlayback('ended');updatePlaybackFrame();}else{seekProject(Math.min(state.duration,end));}});
}
function ensurePlaybackController(){
  if(playbackController)return playbackController;
  playbackController=new EditorOverhaul.PlaybackController({
    clock:authoritativePlaybackTime,
    onTime:(time,meta)=>{state.currentTime=time;updatePlaybackFrame();if(meta.reason==='ended')syncVideo();},
    onLoop:()=>{syncVideo();syncTimelineAudio(true);},
    onStop:()=>{state.playing=false;stopAllPlaybackMedia();const button=document.querySelector('.play-btn');if(button)button.innerHTML=icons.play;}
  });
  return playbackController;
}
function stopProjectPlayback(reason='paused'){
  const mediaTime=authoritativePlaybackTime();if(Number.isFinite(mediaTime))state.currentTime=mediaTime;ensurePlaybackController().pause(reason,false);state.playing=false;stopAllPlaybackMedia();updatePlaybackFrame();const button=document.querySelector('.play-btn');if(button)button.innerHTML=icons.play;
}
function seekProject(time,{sync=true}={}){
  const controller=ensurePlaybackController();controller.configure({duration:state.duration,loop:state.loopPlayback,loopStart:state.loopStart,loopEnd:state.loopEnd});state.currentTime=controller.seek(time);if(sync)syncVideo(true);updatePlaybackFrame();return state.currentTime;
}
function togglePlayback(){
  if(state.playing){stopProjectPlayback();return;}
  recalculateDuration();if(state.currentTime>=state.duration-.001)state.currentTime=0;
  state.playing=true;ensurePreviewAudioContext()?.resume().catch(()=>{});
  playbackSyncTick=0;performanceMonitor=new Phase9.PerformanceMonitor();
  playbackController=ensurePlaybackController();playbackController.play(state.currentTime,{duration:state.duration,rate:1,loop:state.loopPlayback,loopStart:state.loopStart,loopEnd:state.loopEnd});
  // A scrub can rebuild the preview element before its metadata is available.
  // Align it with the project playhead before it is allowed to drive our clock.
  syncVideo(true);syncTimelineAudio(true);
  const button=document.querySelector('.play-btn');if(button)button.innerHTML=icons.pause;
}

function stepFrame(direction){if(state.playing)stopProjectPlayback();const fps=Math.max(1,Number(state.creatorSettings.customFrameRate)||30);seekProject(state.currentTime+direction/fps);render();}
function toggleLoopPlayback(){state.loopPlayback=!state.loopPlayback;const clip=state.clips.find(item=>item.id===state.selected);state.loopStart=clip?clip.start:0;state.loopEnd=clip?clip.start+clip.duration:state.duration;state.creatorSettings.loopPlayback=state.loopPlayback;render();scheduleProjectSave(0);toast(state.loopPlayback?`Looping ${clip?'selected clip':'project'}`:'Loop playback off');}
function setPreviewQuality(value){state.previewQuality=['auto','full','half','quarter'].includes(value)?value:'auto';state.creatorSettings.previewQuality=state.previewQuality;activePreviewQuality=Phase9.previewPolicy({width:state.frameWidth||1920,height:state.frameHeight||1080,clips:state.clips.length,effects:state.clips.filter(item=>item.type==='effect').length,memoryGB:navigator.deviceMemory||8,requested:state.previewQuality});document.body.dataset.previewQuality=activePreviewQuality;scheduleProjectSave(0);render();}
async function fullscreenPreview(){const element=document.querySelector('.preview-wrap');if(!element)return;try{if(document.fullscreenElement)await document.exitFullscreen();else await element.requestFullscreen();}catch(error){toast(error.message||'Fullscreen is unavailable on this device');}}

function showShortcutGuide(){
  if(runtimeMode.platform!=='desktop')return;
  document.querySelector('.shortcut-backdrop')?.remove();
  const groups=[
    ['Project',[['Ctrl + S','Save project'],['Ctrl + I','Import media'],['Ctrl + E','Export video'],['?','Show shortcuts']]],
    ['Edit',[['Ctrl + Z','Undo'],['Ctrl + Y','Redo'],['Ctrl + C','Copy selected clip'],['Ctrl + V','Paste clip at playhead'],['Ctrl + D','Duplicate selected clip'],['Delete','Delete selected clip'],['Shift + Delete','Ripple delete']]],
    ['Timeline',[['Space','Play / pause'],['Ctrl + K','Split at playhead'],['← / →','Move playhead by 0.1s'],['Shift + ← / →','Move playhead by 1s'],['Alt + ← / →','Previous / next keyframe'],['Home / End','Go to start / end'],['+ / −','Zoom timeline'],['S','Toggle snapping']]],
    ['Tools',[['V','Select tool'],['C','Razor tool'],['H','Hand tool'],['T','Text tool'],['M','Mute / unmute preview']]]
  ];
  const wrap=document.createElement('div');wrap.className='modal-backdrop shortcut-backdrop';wrap.innerHTML=`<div class="modal shortcut-modal"><div class="shortcut-head"><div><h2>Keyboard shortcuts</h2><p>Desktop editing controls for Zorifi.</p></div><button class="icon-btn" data-close aria-label="Close">×</button></div><div class="shortcut-groups">${groups.map(([title,items])=>`<section><h3>${title}</h3>${items.map(([keys,label])=>`<div><kbd>${keys}</kbd><span>${label}</span></div>`).join('')}</section>`).join('')}</div><div class="modal-actions"><button class="primary-btn" data-close>Done</button></div></div>`;document.body.appendChild(wrap);const close=()=>wrap.remove();wrap.querySelectorAll('[data-close]').forEach(button=>button.onclick=close);wrap.addEventListener('click',event=>{if(event.target===wrap)close();});
}

function copySelectedClip(){const clip=state.clips.find(item=>item.id===state.selected);if(!clip)return toast('Select a clip to copy');shortcutClipboard=structuredClone(clip);toast(`${clip.name} copied`);}
function pasteShortcutClip(){if(!shortcutClipboard)return toast('Copy a clip first');snapshot();const clip={...structuredClone(shortcutClipboard),id:`${shortcutClipboard.id}-copy-${Date.now()}`,start:Math.max(0,Math.min(state.currentTime,state.duration))};state.clips.push(clip);state.selected=clip.id;recalculateDuration();render();toast(`${clip.name} pasted at the playhead`);}
function duplicateSelectedClip(){const clip=state.clips.find(item=>item.id===state.selected);if(!clip)return toast('Select a clip to duplicate');shortcutClipboard=structuredClone(clip);const nextStart=Math.min(state.duration,clip.start+clip.duration);snapshot();const copy={...structuredClone(clip),id:`${clip.id}-duplicate-${Date.now()}`,start:nextStart,name:`${clip.name} copy`};state.clips.push(copy);state.selected=copy.id;recalculateDuration();render();toast('Clip duplicated');}
function setPlayhead(time){seekProject(Phase8.frameTime(Math.max(0,time),state.creatorSettings.customFrameRate||30));render();}
function timelineHeadWidth(){return runtimeMode.touch?(editorWorkspaceMode==='music'?220:52):94;}
function timelineWidthForZoom(zoom){const minimum=runtimeMode.touch&&editorWorkspaceMode!=='music'?Math.max(180,Math.min(innerWidth,document.querySelector('.timeline-scroll')?.clientWidth||innerWidth)-timelineHeadWidth()-16):runtimeMode.touch?700:600;return Math.max(minimum,Math.round(Math.max(1,state.duration)*zoom*.45));}
