  const zone=e.currentTarget, rect=zone.getBoundingClientRect();
  const move=ev=>{seekProject(EditorOverhaul.dropTime({clientX:ev.clientX,left:rect.left,width:rect.width,duration:state.duration,snap:true,fps:state.creatorSettings.customFrameRate||30}));};
