function recalculateDuration(){
  const end=EditorOverhaul.projectDuration(state.clips,{minimum:1});
  state.duration=Math.max(1,Math.ceil(end*10)/10);
  state.currentTime=Math.min(state.currentTime,state.duration);
  playbackController?.configure({duration:state.duration,loop:state.loopPlayback,loopStart:state.loopStart,loopEnd:state.loopEnd});
}

