  const width=96,height=Math.max(54,Math.round(width*(video.videoHeight||9)/(video.videoWidth||16))),canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const context=canvas.getContext('2d',{willReadFrequently:true});
