function readVideoMetadata(url){
  return new Promise(resolve=>{
    const video=document.createElement('video');
    video.preload='metadata'; video.muted=true;
    video.onloadedmetadata=()=>resolve({duration:Number.isFinite(video.duration)?video.duration:8,width:video.videoWidth,height:video.videoHeight});
    video.onerror=()=>resolve({duration:8,width:0,height:0});
    video.src=url;
  });
}

