    const extension=file.name.toLowerCase().split('.').pop(),type=file.type.startsWith('video')||['mp4','mov','m4v','avi','mkv'].includes(extension)?'video':file.type.startsWith('image')||['jpg','jpeg','png','webp','gif','avif'].includes(extension)?'image':'audio';let url='';
