  const newEdit=pendingNewProject,homeTool=pendingHomeTool;
  if(pendingNewProject){if(state.view==='editor')saveProject();pendingNewProject=false;createNewProject();}
  const progress=document.createElement('div');progress.className='touch-import-progress';progress.setAttribute('role','status');progress.innerHTML=`<i></i><span>Opening ${files.length} ${files.length===1?'file':'files'}…</span>`;document.body.appendChild(progress);
