    const motion=effectiveMotion(clip,time);context.save();context.globalAlpha=motion.opacity;context.globalCompositeOperation=clip.blendMode&&clip.blendMode!=='normal'?clip.blendMode:'source-over';context.filter=MotionEffects.cssFilter(clip,time,(target,property,at,fallback)=>keyframedValue(target,property,at,fallback));context.fillStyle=clip.color||'#ffffff';context.textAlign=clip.align||'center';context.textBaseline='middle';
