    modal.querySelector('.export-status').textContent='Preparing decoders, effects and audio…';sources=await prepareExportSources(renderableClips,audioContext,masterInput||audioDestination);if(!sources.length)throw new Error('No project media could be prepared. Re-import the original files and try again.');
