function vanessaRemoteAvailable(){return isCapacitorNative()||VanessaRouter.remoteAvailable({protocol:location.protocol});}
function cancelVanessaStream(){vanessaStreamEpoch++;vanessaRequestController?.abort();vanessaRequestController=null;vanessaStreamText='';vanessaStreamFailure='';vanessaBusy=false;vanessaActionState='idle';}
function renderVanessaStream(){
 const log=document.querySelector('#vanessa-messages');if(!log)return;
 let preview=log.querySelector('[data-stream-preview]');
 if(!vanessaStreamText){preview?.remove();return;}
 const followEnd=log.scrollHeight-log.scrollTop-log.clientHeight<100;
 if(!preview){preview=document.createElement('article');preview.className='assistant';preview.dataset.streamPreview='';preview.setAttribute('aria-label','Vanessa');preview.innerHTML='<span aria-hidden="true">✦</span><div class="vanessa-message-body"><div class="vanessa-message-text"></div><small>Receiving response…</small></div>';log.appendChild(preview);}
 preview.querySelector('.vanessa-message-text').innerHTML=vanessaFormattedText(vanessaStreamText);log.querySelector('.thinking')?.remove();if(followEnd)log.scrollTop=log.scrollHeight;
}
async function safeVanessaRequest(service,payload,{timeoutMs=120000}={}){
 if(!vanessaRemoteAvailable())return {ok:false,status:0,data:null,error:{kind:'offline',message:'remote unavailable'}};
 const controller=new AbortController(),epoch=vanessaStreamEpoch,userId=currentUser?.id,projectId=state.projectId;vanessaRequestController=controller;const timeout=setTimeout(()=>controller.abort(),timeoutMs);
 const current=()=>epoch===vanessaStreamEpoch&&currentUser?.id===userId&&state.projectId===projectId;
 try{
  const options={method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload),signal:controller.signal};
  if(service!=='vanessa-global')return await VanessaRouter.requestJson(vanessaFetch,vanessaEndpoint(service),options);
  options.body=JSON.stringify({...payload,stream:true});options.headers.accept='text/event-stream';
  const result=await VanessaRouter.requestStream(vanessaFetch,vanessaEndpoint(service),options,text=>{if(!current()){controller.abort();return;}vanessaStreamText=text;renderVanessaStream();});
  if(!current())return {ok:false,status:0,data:null,error:{kind:'cancelled',message:'Conversation changed'}};
  if(result.error?.code==='STREAM_UNSUPPORTED')return await VanessaRouter.requestJson(vanessaFetch,vanessaEndpoint(service),{...options,headers:{'content-type':'application/json'},body:JSON.stringify(payload)});
  if(!result.ok&&vanessaStreamText)vanessaStreamFailure='The response was interrupted before it finished. Please retry.';
  return result;
 }finally{clearTimeout(timeout);if(vanessaRequestController===controller)vanessaRequestController=null;if(current()){vanessaStreamText='';renderVanessaStream();}}
}

