  const priorConversation=Array.isArray(contextHistory)?contextHistory:[],priorUser=[...priorConversation].reverse().find(item=>item.role==='user')?.text||'',priorAssistant=[...priorConversation].reverse().find(item=>item.role==='assistant')?.text||'';
