  if(/(?:create|make|generate).*(?:voiceover|voice over|narration|speech)/.test(text)){const prompt=message.replace(/^.*?(?:create|make|generate)\s+(?:an?\s+)?(?:ai\s+)?(?:voiceover|voice over|narration|speech)\s*/i,'').replace(/^(?:for|saying|that says)\s+/i,'').trim()||message;return {action:'ai_generate_voice',args:{value:prompt}};}
  if(/(?:write|create|generate).*(?:hooks?|openers?)/.test(text))return {action:'ai_generate_hooks',args:{value:message}};
  if(/(?:write|create|generate).*(?:script)/.test(text))return {action:'ai_generate_script',args:{value:message}};
  if(/(?:create|generate|plan).*(?:storyboard|scene plan)/.test(text))return {action:'ai_storyboard',args:{value:message}};
