  if(/account|profile|settings/.test(text))return {action:'account_settings'};
  if(/go home|workspace|dashboard/.test(text))return {action:'home'};
  if(/undo/.test(text))return {action:'undo'};if(/redo/.test(text))return {action:'redo'};
  if(/ripple/.test(text))return {action:'ripple_delete'};if(/duplicate.*clip|copy.*clip|duplicate selected/.test(text))return {action:'duplicate_clip'};if(/delete.*clip|remove.*clip|delete selected/.test(text))return {action:'delete_clip'};if(/split|cut.*clip/.test(text))return {action:'split_clip'};
  if(/(?:mute|unmute).*(?:preview|video|sound)/.test(text))return {action:'mute_preview'};if(/pause/.test(text))return {action:'pause'};if(/play|preview/.test(text))return {action:'play'};
